SELECT
    ,
    EXISTS(SELECT 1 FROM courtship_likes cl
           WHERE cl.from_user_id = #{userId}
             AND cl.to_user_id = p.user_id) AS liked_by_me
FROM courtship_profiles p
LEFT JOIN users u ON u.id = p.user_id
WHERE p.status = 'APPROVED' AND p.user_id != #{userId}
AND p.gender = #{gender}
AND p.region = #{region}
ORDER BY p.updated_at DESC
LIMIT #{size} OFFSET #{offset}

SELECT COUNT(*) FROM courtship_profiles p
WHERE p.status = 'APPROVED' AND p.user_id != #{userId}
AND p.gender = #{gender}
AND p.region = #{region}
